std::string add(const std::string& a, const std::string& b) {
  std::string out;
  int i = a.size() - 1, j = b.size() - 1, carry = 0;
  while (i >= 0 || j >= 0) {
    int sum = carry;
    if (i >= 0) sum += a[i--] - '0';
    if (j >= 0) sum += b[j--] - '0';
    out.push_back('0' + sum % 10);
    carry = sum / 10;
  }
  std::reverse(out.begin(), out.end());
  return out;
}

