std::string addStrings(const std::string& a, const std::string& b) {
  std::string out;
  int i = (int)a.size() - 1, j = (int)b.size() - 1, carry = 0;
  while (i >= 0 || j >= 0 || carry) {      // the carry alone can add one more digit
    int sum = carry;
    if (i >= 0) sum += a[i--] - '0';
    if (j >= 0) sum += b[j--] - '0';
    out.push_back(char('0' + sum % 10));
    carry = sum / 10;
  }
  std::reverse(out.begin(), out.end());   // built from the least significant digit: O(n) total
  return out;
}

