// Grammar:  number   := [sign] (digits ['.' [digits]] | '.' digits) [exponent]
//           exponent := ('e'|'E') [sign] digits
// One pass with three flags instead of an explicit DFA table.
bool isNumber(const std::string& s) {
  bool seenDigit = false, seenDot = false, seenExp = false;
  for (size_t i = 0; i < s.size(); ++i) {
    char c = s[i];
    if (std::isdigit(static_cast<unsigned char>(c))) {
      seenDigit = true;
    } else if (c == '+' || c == '-') {
      // a sign may appear only at the start or right after the exponent letter
      if (i > 0 && s[i - 1] != 'e' && s[i - 1] != 'E') return false;
    } else if (c == '.') {
      if (seenDot || seenExp) return false;      // one dot, and never inside the exponent
      seenDot = true;
    } else if (c == 'e' || c == 'E') {
      if (seenExp || !seenDigit) return false;   // the mantissa needs at least one digit
      seenExp = true;
      seenDigit = false;                         // the exponent needs its own digits
    } else {
      return false;                              // letters, spaces, anything else
    }
  }
  return seenDigit;
}

HEX = set("0123456789abcdefABCDEF")


def is_v4_part(p: str) -> bool:
    if not 1 <= len(p) <= 3 or not all("0" <= c <= "9" for c in p):
        return False                     # ASCII digits only: str.isdigit() accepts '²' etc.
    if len(p) > 1 and p[0] == "0":
        return False                     # no leading zeros
    return int(p) <= 255


def is_v6_part(p: str) -> bool:
    return 1 <= len(p) <= 4 and all(c in HEX for c in p)


def valid_ip_address(ip: str) -> str:
    # split keeps empty strings, so "1..2.3" or a trailing "." gives an empty part
    if ip.count(".") == 3 and all(is_v4_part(p) for p in ip.split(".")):
        return "IPv4"
    if ip.count(":") == 7 and all(is_v6_part(p) for p in ip.split(":")):
        return "IPv6"
    return "Neither"

